mapper.select:
SELECT 
FROM ebook
WHERE pilgrimage_id = #{pilgrimageId} AND ebook_type = #{ebookType}

mapper.update:
UPDATE ebook
SET status = 'FAILED', fail_reason = #{failReason}, pdf_key = NULL
WHERE ebook_id = #{ebookId}

mapper.select:
SELECT  FROM ebook
WHERE user_id = #{userId}
  AND NOT EXISTS (SELECT 1 FROM print_order po WHERE po.ebook_id = ebook.ebook_id)

mapper.delete:
DELETE FROM ebook
WHERE user_id = #{userId}
  AND NOT EXISTS (SELECT 1 FROM print_order po WHERE po.ebook_id = ebook.ebook_id)
